def solve(inputs: dict) -> float:
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        raise KeyError(names[0])
    s = int(pick('s', 'start', 'initial', 'x', 'X'))
    a = int(pick('a', 'multiplier', 'mult'))
    c = int(pick('c', 'increment', 'addend', 'offset'))
    m = int(pick('m', 'modulus', 'mod'))
    n = int(pick('n', 'steps', 'iterations', 'times'))
    for _ in range(n):
        s = (a * s + c) % m
    return s

